Section CANSEC1. Context {rc : runConstT}.
Section FramesD.
Variables (L : alayout) (W : list (Z * Z)) (m m' : amem).
Hypothesis MU : munch W m m'.

Ltac xcell := eapply cells_frameD; [eassumption | exact MU | cbn -[Z.add Z.mul]; assumption].

